/* The Quiet Frontier: bounded, fictional survival systems. Distances are game meters. */
export const SAVE_VERSION=2;
export const ITEMS={alloy:'Titanium alloy',circuit:'Circuit boards',ice:'Water ice',crystal:'Resonant crystal'};
export const SITES=[
{id:'home',name:'Habitat 07',type:'home',pos:[0,0,0],radius:30,region:'THE SHELTER',text:'Your damaged orbital habitat. Dock to refill oxygen and power, store cargo, and fabricate systems.'},
{id:'wreck1',name:'Broken survey skiff',type:'salvage',pos:[120,20,-220],radius:14,region:'THE SHALLOWS',loot:{alloy:4,circuit:2},text:'A survey skiff caught in the debris. Its electronics may still be useful.'},
{id:'ice1',name:'Blue ice seam',type:'ice',pos:[-155,-20,-210],radius:18,region:'THE SHALLOWS',loot:{ice:8},text:'Water ice can support life systems and larger oxygen reserves.'},
{id:'ore1',name:'Titanium outcrop',type:'ore',pos:[-260,65,40],radius:23,region:'THE SHALLOWS',loot:{alloy:7},text:'Metal-rich stone. Strong structures start with simple materials.'},
{id:'wreck2',name:'Cargo spine',type:'salvage',pos:[310,-60,130],radius:20,region:'THE SHALLOWS',loot:{alloy:4,circuit:3},text:'A freight frame twisted by impact. Salvage before leaving the sheltered field.'},
{id:'signal1',name:'The first whisper',type:'signal',pos:[80,50,-430],radius:22,region:'THE SHALLOWS',text:'A repeating pulse. Scan it and bring the measurements home.',record:'The pulse is not random. It repeats every 19 seconds, matching an old habitat time code. Someone was here before your crew.'},
{id:'wreck3',name:'Observatory wreck',type:'salvage',pos:[-450,100,-600],radius:25,region:'THE GLASS BELT',loot:{alloy:6,circuit:4},text:'The old observatory contains alloys and navigation electronics.'},
{id:'crystal1',name:'Resonant garden',type:'crystal',pos:[350,85,-730],radius:26,region:'THE GLASS BELT',loot:{crystal:6},text:'Crystalline growths resonate with the nearby signal. A scanner can study their structure.'},
{id:'ice2',name:'Drifting ice shelf',type:'ice',pos:[-650,-100,140],radius:35,region:'THE GLASS BELT',loot:{ice:8},text:'Deep ice reserves. Larger life-support systems need larger water reserves.'},
{id:'ore2',name:'Iron cathedral',type:'ore',pos:[650,-70,-350],radius:34,region:'THE GLASS BELT',loot:{alloy:7},text:'A vast metallic formation in the debris stream.'},
{id:'signal2',name:'The listening array',type:'signal',pos:[-500,70,-890],radius:28,region:'THE GLASS BELT',needs:'scanner',text:'Resolve the signal with a spectral scanner.',record:'The listening array was built to observe Vesper. Its last log describes a luminous field beneath the cloud tops. The transmissions were warnings, not distress calls.'},
{id:'wreck4',name:'Long-range relay',type:'salvage',pos:[760,130,-820],radius:24,region:'THE GLASS BELT',loot:{alloy:5,circuit:4},text:'Long-range circuitry. Useful for transmitting science back to Earth.'},
{id:'crystal2',name:'Silent grove',type:'crystal',pos:[-850,-50,-960],radius:30,region:'THE OUTER VEIL',loot:{crystal:7},text:'A second growth beyond the listening array. The field is colder here.'},
{id:'ore3',name:'The last bastion',type:'ore',pos:[850,180,-1150],radius:38,region:'THE OUTER VEIL',loot:{alloy:7},text:'An exposed metal deposit near the radiation boundary.'},
{id:'signal3',name:'The quiet engine',type:'signal',pos:[180,-50,-1640],radius:38,region:'THE OUTER VEIL',needs:'shield',text:'A radiation-shielded approach is required to recover the final record.',record:'The engine never failed. The crew shut it down to protect the field they had discovered. Their return coordinates are intact. You can leave — and bring their observations home.'}
];
export const RECIPES=[
{id:'life',name:'Habitat life support',category:'HABITAT',cost:{alloy:4,circuit:1,ice:2},credits:8,mass:30,load:35,text:'Restore the habitat’s long-term oxygen loop. Required for departure readiness.'},
{id:'solar',name:'Deployable solar array',category:'POWER',cost:{alloy:3,circuit:1},credits:8,mass:28,load:0,generation:120,text:'Add 120 units of design power. Makes room for demanding upgrades.'},
{id:'oxygen',name:'Extended oxygen tank',category:'SURVIVAL',cost:{alloy:3,ice:3},credits:10,mass:18,load:5,text:'Increase expedition oxygen from 100 to 170. Explore farther before returning.'},
{id:'thruster',name:'Efficient maneuvering drive',category:'PROPULSION',cost:{alloy:4,circuit:2},credits:12,mass:24,load:20,text:'Increase cruise speed from 38 to 58 m/s. Higher speed still consumes expedition power.'},
{id:'scanner',name:'Spectral scanner',category:'SCIENCE',cost:{alloy:2,circuit:2,crystal:1},credits:10,mass:12,load:15,text:'Resolve the listening array. Survey data must be returned to the habitat.'},
{id:'shield',name:'Radiation shield',category:'STRUCTURE',cost:{alloy:4,crystal:2},credits:14,mass:28,load:25,text:'Protect the spacecraft in the Outer Veil. Unlock the final signal.'},
{id:'cargo',name:'Cargo lattice',category:'STRUCTURE',cost:{alloy:3},credits:7,mass:20,load:0,text:'Increase expedition cargo capacity from 18 to 30 units.'},
{id:'relay',name:'Long-range science relay',category:'COMMUNICATIONS',cost:{alloy:2,circuit:3,crystal:2},credits:15,mass:35,load:20,text:'Return recovered observations home. Requires a restored habitat oxygen loop.'},
{id:'escape',name:'Return-stage integration',category:'MISSION',cost:{alloy:6,circuit:4,crystal:4},credits:30,mass:80,load:20,text:'Integrate a return stage after all three surveys are returned and the relay is online.'}
];
export const length=v=>Math.hypot(...v);
export const distance=(a,b)=>Math.hypot(a[0]-b[0],a[1]-b[1],a[2]-b[2]);
export const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
export function create(){return {version:SAVE_VERSION,pos:[0,0,110],yaw:0,pitch:0,oxygen:100,energy:100,hull:100,inventory:{alloy:0,circuit:0,ice:0,crystal:0},storage:{alloy:0,circuit:0,ice:0,crystal:0},remaining:Object.fromEntries(SITES.filter(s=>s.loot).map(s=>[s.id,{...s.loot}])),modules:[],surveys:{},credits:125,selected:'wreck1',docked:false,elapsed:0,recoveries:0,won:false,log:['Habitat 07 is damaged. Recover alloy, electronics and water ice. Restore life support, follow the three signals, and build a way home.']};}
export function restore(raw){if(raw?.version!==SAVE_VERSION)throw Error('Unsupported save.');if(!Array.isArray(raw.pos)||raw.pos.length!==3||!raw.pos.every(Number.isFinite)||!raw.inventory||!raw.storage||!raw.remaining||!Array.isArray(raw.modules))throw Error('Incomplete expedition save.');const s=create();for(const k of ['pos'])if(Array.isArray(raw[k])&&raw[k].length===3&&raw[k].every(Number.isFinite))s[k]=raw[k].map(x=>clamp(x,-2500,2500));for(const [k,a,b] of [['yaw',-10000,10000],['pitch',-1.35,1.35],['oxygen',0,170],['energy',0,100],['hull',0,100],['elapsed',0,1e9],['recoveries',0,1e6]])if(Number.isFinite(raw[k]))s[k]=clamp(raw[k],a,b);s.modules=[...new Set(Array.isArray(raw.modules)?raw.modules:[])].filter(id=>RECIPES.some(r=>r.id===id));s.credits=125-s.modules.reduce((n,id)=>n+RECIPES.find(r=>r.id===id).credits,0);for(const k of ['inventory','storage'])for(const id of Object.keys(ITEMS))s[k][id]=clamp(Math.floor(Number(raw[k]?.[id])||0),0,1000);for(const site of SITES.filter(x=>x.loot))for(const id of Object.keys(site.loot))s.remaining[site.id][id]=clamp(Math.floor(Number(raw.remaining?.[site.id]?.[id])||0),0,site.loot[id]);for(const id of ['signal1','signal2','signal3'])if(['buffered','returned'].includes(raw.surveys?.[id]))s.surveys[id]=raw.surveys[id];s.selected=SITES.some(x=>x.id===raw.selected)?raw.selected:'home';s.docked=!!raw.docked&&distance(s.pos,[0,0,0])<100;s.won=!!raw.won&&s.modules.includes('escape')&&Object.values(s.surveys).filter(x=>x==='returned').length===3;s.log=Array.isArray(raw.log)?raw.log.slice(-40).map(x=>String(x).slice(0,500)):s.log;s.oxygen=Math.min(s.oxygen,limits(s).oxygen);const d=design(s);if(d.mass>d.capacity||d.power>d.generation||s.credits<0||cargo(s)>limits(s).cargo)throw Error('Saved spacecraft violates its design limits.');if(s.modules.includes('relay')&&!s.modules.includes('life'))throw Error('Saved relay requires habitat life support.');return s;}
export function limits(s){return {oxygen:s.modules.includes('oxygen')?170:100,cargo:s.modules.includes('cargo')?30:18,speed:s.modules.includes('thruster')?58:38};}
export const cargo=s=>Object.values(s.inventory).reduce((a,x)=>a+x,0);
export function design(s){return {mass:60+s.modules.reduce((a,id)=>a+RECIPES.find(r=>r.id===id).mass,0),capacity:300,power:25+s.modules.reduce((a,id)=>a+RECIPES.find(r=>r.id===id).load,0),generation:120+s.modules.reduce((a,id)=>a+(RECIPES.find(r=>r.id===id).generation||0),0),spent:125-s.credits,budget:125};}
export const addLog=(s,message)=>{s.log.push(message);s.log=s.log.slice(-40);};
export function nearest(s){let near=null;for(const site of SITES){const d=distance(s.pos,site.pos);const range=site.type==='home'?95:site.radius+48;if(d<range&&(!near||d<near.distance))near={...site,distance:d};}return near;}
export function forward(yaw,pitch){return [-Math.sin(yaw)*Math.cos(pitch),Math.sin(pitch),-Math.cos(yaw)*Math.cos(pitch)];}
export function orient(s,pos){const dx=pos[0]-s.pos[0],dy=pos[1]-s.pos[1],dz=pos[2]-s.pos[2];s.yaw=Math.atan2(-dx,-dz);s.pitch=clamp(Math.atan2(dy,Math.hypot(dx,dz)),-1.35,1.35);}
export function tick(s,dt,input={}){dt=clamp(Number(dt)||0,0,.1);if(s.won)return null;s.elapsed+=dt;if(s.docked){s.oxygen=limits(s).oxygen;s.energy=100;return null;}s.yaw+=(input.turn||0)*dt*1.15;s.pitch=clamp(s.pitch+(input.tilt||0)*dt,-1.35,1.35);let f=input.forward||0,side=input.side||0,up=input.up||0;
 if(input.auto){const target=SITES.find(x=>x.id===s.selected);if(target){orient(s,target.pos);const stop=target.type==='home'?70:target.radius+32;f=distance(s.pos,target.pos)>stop?1:0;side=0;up=0;}}
 const vector=forward(s.yaw,s.pitch),right=[Math.cos(s.yaw),0,-Math.sin(s.yaw)];let movement=vector.map((v,i)=>v*f+right[i]*side+(i===1?up:0));if(input.auto&&f>0){for(const obstacle of SITES){if(obstacle.id===s.selected)continue;const rel=obstacle.pos.map((v,i)=>v-s.pos[i]),along=rel.reduce((n,v,i)=>n+v*vector[i],0),safe=obstacle.radius+20;if(along<=0||along>safe+85)continue;let away=rel.map((v,i)=>vector[i]*along-v),perp=length(away);if(perp>=safe)continue;if(perp<.001){away=[vector[2],0,-vector[0]];perp=length(away)||1;}const force=(1-Math.min(perp/safe,1))*2.8;movement=movement.map((v,i)=>v+away[i]/perp*force);}}const n=length(movement);const boost=!!input.boost&&s.energy>5,speed=limits(s).speed*(boost?1.5:1)*(s.energy>0?1:.3);const previous=[...s.pos];if(n>0)for(let i=0;i<3;i++)s.pos[i]=clamp(s.pos[i]+movement[i]/Math.max(1,n)*speed*dt,-2400,2400);
 s.oxygen=Math.max(0,s.oxygen-.42*dt);s.energy=Math.max(0,s.energy-(.035+(n>0?.22:0)+(boost?.55:0))*dt);
 if(distance(s.pos,[0,0,0])>1300&&!s.modules.includes('shield'))s.hull=Math.max(0,s.hull-1.8*dt);
 for(const site of SITES){if(distance(s.pos,site.pos)<site.radius+5){s.pos=previous;s.hull=Math.max(0,s.hull-7*dt);break;}}
 if(s.oxygen<=0||s.hull<=0){s.pos=[0,0,75];s.oxygen=limits(s).oxygen;s.energy=100;s.hull=65;s.docked=true;s.recoveries++;for(const id of Object.keys(s.surveys))if(s.surveys[id]==='buffered')delete s.surveys[id];addLog(s,'Emergency recovery returned you to Habitat 07. Cargo survived; unreturned survey data was lost. Repair and plan the next expedition.');return 'recovered';}return null;}
export function interact(s){if(s.won)throw Error('The mission is complete.');const site=nearest(s);if(!site)throw Error('Approach a marked site to interact.');if(site.type==='home')return dock(s);if(site.type==='signal'){if(site.needs&&!s.modules.includes(site.needs))throw Error(site.needs==='scanner'?'Fabricate a spectral scanner to resolve this record.':'Fabricate radiation shielding before approaching the quiet engine.');if(s.surveys[site.id])throw Error('Survey already recovered. Dock to return buffered data.');s.surveys[site.id]='buffered';addLog(s,site.name+': '+site.record+' Survey buffered — return it to Habitat 07.');return 'scanned';}
 const loot=s.remaining[site.id];if(!loot||Object.values(loot).every(x=>x<=0))throw Error('This deposit is depleted.');let space=limits(s).cargo-cargo(s),taken=0;if(space<=0)throw Error('Cargo full. Dock at the habitat to store materials.');for(const id of Object.keys(loot)){const n=Math.min(loot[id],space);s.inventory[id]+=n;loot[id]-=n;space-=n;taken+=n;}addLog(s,`${site.name}: recovered ${taken} cargo units.`);return 'salvaged';}
export function dock(s){if(distance(s.pos,[0,0,0])>95)throw Error('Approach Habitat 07 to dock.');s.docked=true;s.oxygen=limits(s).oxygen;s.energy=100;for(const id of Object.keys(ITEMS)){s.storage[id]+=s.inventory[id];s.inventory[id]=0;}let returned=0;for(const id of Object.keys(s.surveys))if(s.surveys[id]==='buffered'){s.surveys[id]='returned';returned++;}addLog(s,returned?`Docked. ${returned} science record${returned>1?'s':''} returned. Materials stored; oxygen and expedition power restored.`:'Docked. Materials stored; oxygen and expedition power restored.');return 'docked';}
export function canCraft(s,id){const r=RECIPES.find(x=>x.id===id);if(!r)return {ok:false,reason:'Unknown blueprint.'};if(!s.docked)return {ok:false,reason:'Dock at Habitat 07 to fabricate.'};if(s.modules.includes(id))return {ok:false,reason:'Already installed.'};if(id==='relay'&&!s.modules.includes('life'))return {ok:false,reason:'Restore habitat life support first.'};if(id==='escape'&&(!s.modules.includes('relay')||['signal1','signal2','signal3'].some(x=>s.surveys[x]!=='returned')))return {ok:false,reason:'Install the relay and return all three signal surveys.'};if(s.credits<r.credits)return {ok:false,reason:'Insufficient mission budget.'};const d=design(s);if(d.mass+r.mass>d.capacity)return {ok:false,reason:'Mass capacity exceeded. Choose fewer optional modules.'};if(d.power+r.load>d.generation+(r.generation||0))return {ok:false,reason:'Power capacity exceeded. Add a solar array.'};for(const [key,n] of Object.entries(r.cost))if(s.inventory[key]+s.storage[key]<n)return {ok:false,reason:'Gather '+ITEMS[key]+'.'};return {ok:true,reason:'Ready to fabricate.'};}
export function craft(s,id){const check=canCraft(s,id);if(!check.ok)throw Error(check.reason);const r=RECIPES.find(x=>x.id===id);for(const [key,n] of Object.entries(r.cost)){const stored=Math.min(n,s.storage[key]);s.storage[key]-=stored;s.inventory[key]-=n-stored;}s.credits-=r.credits;s.modules.push(id);s.oxygen=limits(s).oxygen;addLog(s,`${r.name} installed. ${r.mass} kg added to the mission design.`);return r;}
export function repair(s){if(!s.docked)throw Error('Dock before repairing the hull.');if(s.hull>=100)throw Error('Hull is already intact.');const total=s.storage.alloy+s.inventory.alloy;if(total<2)throw Error('Hull repair requires 2 alloy.');const n=Math.min(2,s.storage.alloy);s.storage.alloy-=n;s.inventory.alloy-=2-n;s.hull=100;addLog(s,'Hull repaired with 2 alloy.');}
export function launchReturn(s){if(!s.docked||!s.modules.includes('escape')||!s.modules.includes('relay')||['signal1','signal2','signal3'].some(x=>s.surveys[x]!=='returned'))throw Error('Finish the return-stage blueprint and return every survey first.');s.won=true;addLog(s,'Departure confirmed. The observations of Vesper are on their way home. You leave the frontier brighter than you found it.');}
export function objective(s){if(!s.modules.includes('life'))return {title:'Restore your shelter',text:'Recover alloy, circuits and ice. Dock at Habitat 07 and fabricate life support.',target:(s.inventory.alloy+s.storage.alloy<4?'wreck1':s.inventory.circuit+s.storage.circuit<1?'wreck2':s.inventory.ice+s.storage.ice<2?'ice1':'home')};if(s.surveys.signal1!=='returned')return {title:'Follow the first whisper',text:'Scan the nearby signal. Return its observations to the habitat.',target:s.surveys.signal1?'home':'signal1'};if(!s.modules.includes('scanner'))return {title:'Build a spectral scanner',text:'Recover resonant crystal from the garden. Build a scanner to understand the next signal.',target:'crystal1'};if(s.surveys.signal2!=='returned')return {title:'Read the listening array',text:'Scan the array in the Glass Belt and return its record.',target:s.surveys.signal2?'home':'signal2'};if(!s.modules.includes('shield'))return {title:'Prepare for the Outer Veil',text:'Fabricate radiation shielding. Consider oxygen and propulsion upgrades for the long expedition.',target:'crystal2'};if(s.surveys.signal3!=='returned')return {title:'Reach the quiet engine',text:'Recover the final record beyond the radiation boundary. Bring the data home.',target:s.surveys.signal3?'home':'signal3'};if(!s.modules.includes('relay'))return {title:'Make contact',text:'Build the science relay to transmit your discoveries home.',target:'home'};if(!s.modules.includes('escape'))return {title:'Design your return',text:'Gather the remaining materials. Keep mass, power and budget feasible while integrating the return stage.',target:'home'};return {title:s.won?'A way home':'Leave a brighter frontier',text:s.won?'Your mission is complete. Every observation reached home.':'The return stage is ready. Launch from the habitat when you are ready.',target:'home'};}

export function dismantle(s,id){if(!s.docked||s.won)throw Error('Dock before reclaiming a module.');const r=RECIPES.find(x=>x.id===id);if(!r||!s.modules.includes(id))throw Error('Module is not installed.');if(id==='life'&&s.modules.includes('relay'))throw Error('Reclaim the relay before life support.');const next={...s,modules:s.modules.filter(x=>x!==id)};if(design(next).power>design(next).generation)throw Error('Reclaim power-consuming modules before the solar array.');s.modules=next.modules;s.credits+=r.credits;for(const [key,n]of Object.entries(r.cost))s.storage[key]+=n;s.oxygen=Math.min(s.oxygen,limits(s).oxygen);addLog(s,r.name+' reclaimed. Materials and budget returned to storage.');}
